import React, { useEffect, useMemo, useState } from "react";
import { createRoot } from "react-dom/client";
import "../styles/page.css";
import { clearHistory, deleteHistoryItem, getStorage, toggleHistoryFavorite } from "../shared/storage";
import type { AssistantSettings, HistoryItem } from "../shared/types";

function HistoryApp() {
  const [items, setItems] = useState<HistoryItem[]>([]);
  const [settings, setSettings] = useState<AssistantSettings>();
  const [query, setQuery] = useState("");

  useEffect(() => {
    void getStorage().then((data) => {
      setItems(data.history);
      setSettings(data.settings);
    });
  }, []);

  const filtered = useMemo(() => items.filter((item) => `${item.selection.text} ${item.result} ${item.actionName} ${item.prompt}`.toLowerCase().includes(query.toLowerCase())), [items, query]);
  const accent = settings?.defaultSelectionAction === "creative" ? "#7c3aed" : "#2563eb";

  return (
    <main className="min-h-screen bg-[#f7f8fb] px-5 py-6 text-slate-950">
      <div className="mx-auto max-w-5xl">
        <header className="mb-6 flex flex-wrap items-center justify-between gap-3">
          <div>
            <h1 className="text-2xl font-bold tracking-normal" style={{ color: accent }}>History</h1>
            <p className="mt-1 text-sm text-slate-500">Minimal interaction history. Items auto-expire after 7 days unless favorited.</p>
          </div>
          <div className="flex gap-2">
            <button className="focus-ring inline-flex items-center gap-2 rounded-xl border bg-white px-4 py-2 text-sm font-bold" style={{ borderColor: `${accent}44`, color: accent }} onClick={() => {
              const blob = new Blob([JSON.stringify(items, null, 2)], { type: "application/json" });
              const link = document.createElement("a");
              link.href = URL.createObjectURL(blob);
              link.download = "ai-context-history.json";
              link.click();
              URL.revokeObjectURL(link.href);
            }}>Export</button>
            <button className="focus-ring inline-flex items-center gap-2 rounded-xl bg-red-600 px-4 py-2 text-sm font-bold text-white" onClick={async () => {
              await clearHistory();
              setItems([]);
            }}>Clear</button>
          </div>
        </header>
        <input className="focus-ring mb-4 w-full rounded-2xl border bg-white px-4 py-3" style={{ borderColor: `${accent}33` }} placeholder="Search history..." value={query} onChange={(event) => setQuery(event.target.value)} />
        <div className="grid gap-3">
          {filtered.map((item) => (
            <article key={item.id} className="rounded-2xl border bg-white p-4 shadow-sm" style={{ borderColor: item.favorite ? accent : `${accent}22` }}>
              <div className="mb-2 flex flex-wrap items-center justify-between gap-2">
                <div className="flex items-center gap-2 text-sm font-bold">
                  <span style={{ color: accent }}>{item.actionName}</span>
                  <span className="rounded-full bg-slate-100 px-2 py-1 text-xs text-slate-500">{item.provider} · {item.model}</span>
                </div>
                <div className="flex items-center gap-2">
                  <span className="text-xs text-slate-500">{new Date(item.createdAt).toLocaleString()}</span>
                  <button
                    className="focus-ring grid h-8 w-8 place-items-center rounded-lg border"
                    style={{ borderColor: `${accent}44`, color: item.favorite ? accent : undefined }}
                    onClick={async () => setItems(await toggleHistoryFavorite(item.id))}
                    title="Favorite"
                  >
                    {item.favorite ? "★" : "☆"}
                  </button>
                  <button
                    className="focus-ring grid h-8 w-8 place-items-center rounded-lg border border-slate-200 text-red-600"
                    onClick={async () => {
                      await deleteHistoryItem(item.id);
                      setItems((current) => current.filter((entry) => entry.id !== item.id));
                    }}
                    title="Delete"
                  >
                    ×
                  </button>
                </div>
              </div>
              <p className="rounded-xl bg-slate-50 p-3 text-sm text-slate-500">{item.selection.text}</p>
              <p className="mt-2 text-xs font-semibold text-slate-500">{item.prompt}</p>
              <p className="mt-3 whitespace-pre-wrap text-sm leading-6 text-slate-900">{item.result}</p>
            </article>
          ))}
          {filtered.length === 0 && <p className="rounded-2xl border border-dashed border-slate-300 bg-white p-8 text-center text-slate-500">No history yet.</p>}
        </div>
      </div>
    </main>
  );
}

createRoot(document.getElementById("root")!).render(<HistoryApp />);
